begin;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the debates in Akbar''s Ibadat Khana:', body_hi = 'अकबर के इबादतख़ाने की बहसों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The early debates among Sunni scholars, and between Sunnis and Shias, turned into such personal attacks that Akbar was disillusioned with the orthodox ulema; from about 1578 he invited Brahmanas, Jains, Zoroastrians and, from 1580, Jesuits from Goa. Statement 3 is wrong: Akbar moved the other way, towards toleration of all faiths. He stopped the debates in the early 1580s and later formed a small circle of disciples, but never imposed a state religion.', explanation_hi = 'कथन 1 और 2 सही हैं। सुन्नी विद्वानों के बीच, और सुन्नियों तथा शियाओं के बीच, शुरुआती बहसें इतने व्यक्तिगत हमलों में बदल गईं कि अकबर का कट्टर उलेमा से मोहभंग हो गया; लगभग 1578 से उन्होंने ब्राह्मणों, जैनों, पारसियों और 1580 से गोवा के जेसुइटों को बुलाया। कथन 3 गलत है: अकबर उलटी दिशा में, सभी धर्मों के प्रति सहिष्णुता की ओर बढ़े। उन्होंने 1580 के दशक के आरंभ में बहसें रोक दीं और बाद में शिष्यों का एक छोटा मंडल बनाया, पर कभी कोई राजधर्म नहीं थोपा।', concept_group_id = 'medieval-akbar-court-ibadat-khana', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["The Ibadat Khana, built at Fatehpur Sikri in 1575, was at first meant for debates among Muslim scholars only, and was later opened to followers of other faiths.", "The bitter quarrels among the ulema there helped turn Akbar towards a wider view of all religions.", "The debates ended with Akbar declaring Islam the sole religion of the state."], "statements_hi": ["1575 में फ़तेहपुर सीकरी में बना इबादतख़ाना पहले केवल मुस्लिम विद्वानों की बहसों के लिए था, और बाद में अन्य धर्मों के अनुयायियों के लिए खोला गया।", "वहाँ उलेमा के कटु झगड़ों ने अकबर को सभी धर्मों के प्रति व्यापक दृष्टि की ओर मोड़ने में मदद दी।", "बहसें अकबर द्वारा इस्लाम को राज्य का एकमात्र धर्म घोषित करने के साथ समाप्त हुईं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-akbar-court-ibadat-khana' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'At Panipat in 1526 Babur, with a much smaller army, defeated Ibrahim Lodi. Consider the following statements:', body_hi = '1526 में पानीपत में बाबर ने बहुत छोटी सेना के साथ इब्राहीम लोदी को हराया। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Babur dug in behind a line of carts and screens, used his guns and matchlocks against the massed elephants and cavalry, and sent horsemen round the flanks to attack from the rear. Ibrahim had alienated many nobles; Daulat Khan Lodi, governor of the Punjab, and others had invited Babur. Statement 3 is wrong: Panipat gave him Delhi and Agra, but he still had to defeat Rana Sanga of Mewar and then the Afghans of the east before his hold on north India was secure.', explanation_hi = 'कथन 1 और 2 सही हैं। बाबर ने गाड़ियों और ओट की पंक्ति के पीछे मोर्चा बाँधा, हाथियों और घुड़सवारों के झुंड के विरुद्ध अपनी तोपों और तोड़ेदार बंदूक़ों का उपयोग किया, और पीछे से हमले के लिए घुड़सवारों को बग़लों से घुमाया। इब्राहीम ने कई सामंतों को नाराज़ कर दिया था; पंजाब के सूबेदार दौलत ख़ान लोदी और अन्य ने बाबर को बुलाया था। कथन 3 गलत है: पानीपत ने उसे दिल्ली और आगरा दिए, पर उत्तर भारत पर अपनी पकड़ पक्की करने से पहले उसे मेवाड़ के राणा सांगा और फिर पूर्व के अफ़ग़ानों को हराना पड़ा।', concept_group_id = 'medieval-babur-first-panipat-1526', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["His field artillery and the tulughma tactic of flanking and encircling the enemy help explain his victory over larger numbers.", "Discontent among Ibrahim Lodi''s own nobles, some of whom had invited Babur, weakened Ibrahim''s position.", "The victory at once gave Babur control of the whole of north India, including Rajputana and Bengal."], "statements_hi": ["उसका मैदानी तोपख़ाना और शत्रु को बग़ल से घेरने की तुलुग़मा रणनीति बड़ी संख्या पर उसकी विजय की व्याख्या करते हैं।", "इब्राहीम लोदी के अपने सामंतों के असंतोष ने, जिनमें से कुछ ने बाबर को बुलाया था, इब्राहीम की स्थिति कमज़ोर की।", "इस विजय ने बाबर को तुरंत राजपूताना और बंगाल सहित पूरे उत्तर भारत का नियंत्रण दे दिया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-babur-first-panipat-1526' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the Chishti order in India:', body_hi = 'भारत में चिश्ती सिलसिले के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct. The Chishtis generally refused grants and posts from the Sultans and avoided the court, living simply on unasked gifts, which gave them a moral standing with rich and poor alike. Their khanqahs had open kitchens and received Hindus and Muslims, scholars and peasants; they used local idioms and music to reach people. Khwaja Moinuddin Chishti settled at Ajmer in the late twelfth century, and his dargah became one of the great places of pilgrimage.', explanation_hi = 'तीनों कथन सही हैं। चिश्ती प्रायः सुल्तानों से अनुदान और पद लेने से मना करते और दरबार से बचते थे, बिना माँगे मिले उपहारों पर सादगी से रहते थे, जिससे अमीर-ग़रीब सभी में उनकी नैतिक प्रतिष्ठा बनी। उनकी ख़ानक़ाहों में खुले लंगर थे और हिंदू-मुसलमान, विद्वान और किसान सभी आते थे; वे लोगों तक पहुँचने के लिए स्थानीय मुहावरों और संगीत का उपयोग करते थे। ख़्वाजा मुईनुद्दीन चिश्ती बारहवीं सदी के अंत में अजमेर में बसे, और उनकी दरगाह सबसे बड़े तीर्थों में से एक बन गई।', concept_group_id = 'medieval-chishti-sufi-order', source_citation = 'NCERT Class XII, Themes in Indian History', question_data = '{"statements": ["Its saints generally kept their distance from the court, which helped them win the trust of ordinary people.", "Their khanqahs were open to visitors of every class and creed.", "The order took root at Ajmer, where Moinuddin Chishti settled."], "statements_hi": ["इसके संत प्रायः दरबार से दूरी रखते थे, जिससे उन्हें आम लोगों का विश्वास जीतने में मदद मिली।", "उनकी ख़ानक़ाहें हर वर्ग और पंथ के आगंतुकों के लिए खुली थीं।", "सिलसिले ने अजमेर में जड़ें जमाईं, जहाँ मुईनुद्दीन चिश्ती बसे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-chishti-sufi-order' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about Dara Shikoh:', body_hi = 'दारा शिकोह के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Shah Jahan''s eldest son had the Upanishads translated in 1657 as the ''Great Secret''; the French scholar Anquetil-Duperron put this Persian version into Latin in 1801-02, and through it European thinkers first read the Upanishads. In his Majma-ul-Bahrain (''Mingling of the Two Oceans'') Dara argued that Sufism and Vedanta differ mainly in words. Statement 2 is wrong: the work was his own, and Aurangzeb, who defeated him in the war of succession, had him executed in 1659.', explanation_hi = 'केवल कथन 1 सही है। शाहजहाँ के ज्येष्ठ पुत्र ने 1657 में उपनिषदों का ''महान रहस्य'' के रूप में अनुवाद करवाया; फ़्रांसीसी विद्वान आंक्वेतिल-दुपेरों ने 1801-02 में इस फ़ारसी रूपांतर को लैटिन में किया, और इसी से यूरोपीय चिंतकों ने पहली बार उपनिषद पढ़े। अपनी मजमा-उल-बहरैन (''दो समुद्रों का मिलन'') में दारा ने तर्क दिया कि सूफ़ीवाद और वेदांत मुख्यतः शब्दों में भिन्न हैं। कथन 2 गलत है: यह कार्य उनका अपना था, और उत्तराधिकार युद्ध में उन्हें हराने वाले औरंगज़ेब ने 1659 में उन्हें मरवा दिया।', concept_group_id = 'medieval-dara-shikoh', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["His Persian translation of fifty Upanishads, the Sirr-i-Akbar, later reached Europe through a Latin version.", "He had the Upanishads translated at the order of his brother Aurangzeb."], "statements_hi": ["पचास उपनिषदों का उनका फ़ारसी अनुवाद, सिर्र-ए-अकबर, बाद में एक लैटिन रूपांतर के माध्यम से यूरोप पहुँचा।", "उन्होंने अपने भाई औरंगज़ेब के आदेश पर उपनिषदों का अनुवाद करवाया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-dara-shikoh' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following settlements:', body_hi = 'निम्नलिखित बस्तियों पर विचार कीजिए:', explanation = 'Two of them were Danish. The Danish East India Company held Tranquebar (Tharangambadi) on the Coromandel coast from 1620 and Serampore on the Hughli from 1755; the Serampore mission later ran a famous press and college. Chandernagore was a French settlement, from the 1690s, and Pulicat, north of Madras, was the Dutch headquarters on the Coromandel coast for many years. The Danes sold their Indian possessions to the British in 1845.', explanation_hi = 'इनमें से दो डेनिश थीं। डेनिश ईस्ट इंडिया कंपनी के पास 1620 से कोरोमंडल तट पर ट्रांक्वेबार (तरंगमबाड़ी) और 1755 से हुगली पर सेरामपुर था; सेरामपुर मिशन ने बाद में एक प्रसिद्ध छापाख़ाना और कॉलेज चलाया। चंदननगर 1690 के दशक से फ़्रांसीसी बस्ती था, और मद्रास के उत्तर में पुलिकट कई वर्षों तक कोरोमंडल तट पर डचों का मुख्यालय रहा। डेनों ने 1845 में अपनी भारतीय बस्तियाँ अंग्रेज़ों को बेच दीं।', concept_group_id = 'medieval-european-companies', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Tranquebar", "Serampore", "Chandernagore", "Pulicat"], "statements_hi": ["ट्रांक्वेबार", "सेरामपुर", "चंदननगर", "पुलिकट"], "closing": "How many of the above were Danish settlements?", "closing_hi": "उपर्युक्त में से कितनी डेनिश बस्तियाँ थीं?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-european-companies' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about Guru Nanak:', body_hi = 'गुरु नानक के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Guru Nanak (1469-1539), born at Talwandi, now Nankana Sahib, taught that liberation comes through remembering the one God''s name (nam), honest work and sharing, not through ritual, pilgrimage or caste. Statement 2 is wrong: after his travels he settled at Kartarpur on the Ravi, where his followers lived as householders, working, worshipping and eating together; Amritsar grew later, around the town founded by the fourth Guru. Statement 3 is wrong: the Khalsa was founded in 1699 by the tenth Guru, Guru Gobind Singh.', explanation_hi = 'केवल कथन 1 सही है। तलवंडी, अब ननकाना साहिब, में जन्मे गुरु नानक (1469-1539) ने सिखाया कि मुक्ति कर्मकांड, तीर्थ या जाति से नहीं, बल्कि एक ईश्वर के नाम के स्मरण, ईमानदार श्रम और बाँटकर खाने से मिलती है। कथन 2 गलत है: अपनी यात्राओं के बाद वे रावी पर करतारपुर में बसे, जहाँ उनके अनुयायी गृहस्थों के रूप में काम करते, उपासना करते और साथ भोजन करते थे; अमृतसर बाद में चौथे गुरु द्वारा बसाए नगर के आसपास बढ़ा। कथन 3 गलत है: ख़ालसा की स्थापना 1699 में दसवें गुरु, गुरु गोबिंद सिंह, ने की।', concept_group_id = 'medieval-guru-nanak', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["He taught devotion to one formless God and rejected caste distinctions and empty ritual.", "He spent his last years at Amritsar.", "He founded the Khalsa."], "statements_hi": ["उन्होंने एक निराकार ईश्वर की भक्ति सिखाई और जाति-भेद तथा खोखले कर्मकांड को अस्वीकार किया।", "उन्होंने अपने अंतिम वर्ष अमृतसर में बिताए।", "उन्होंने ख़ालसा की स्थापना की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-guru-nanak' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Alauddin''s general marched against the Yadavas, the Kakatiyas, the Hoysalas and the Pandyas, and came back with elephants, horses and treasure; except for Devagiri, which was later annexed, the southern kingdoms were left to their rulers on condition that they paid tribute, since Delhi could not govern so far away. Statement 2 is wrong: Kafur was a slave, bought at Cambay during the conquest of Gujarat, who rose high in Alauddin''s favour.', explanation_hi = 'केवल कथन 1 सही है। अलाउद्दीन का सेनापति यादवों, काकतीयों, होयसलों और पांड्यों के विरुद्ध गया और हाथी, घोड़े और ख़ज़ाना लेकर लौटा; बाद में मिलाए गए देवगिरि को छोड़कर दक्षिणी राज्य कर देने की शर्त पर उनके शासकों के पास रहने दिए गए, क्योंकि दिल्ली इतनी दूर शासन नहीं कर सकती थी। कथन 2 गलत है: काफ़ूर एक दास था, जिसे गुजरात विजय के दौरान खंभात में ख़रीदा गया था, और जो अलाउद्दीन की कृपा से ऊँचे पद तक पहुँचा।', concept_group_id = 'medieval-malik-kafur', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Malik Kafur''s campaigns in the south between 1307 and 1311 aimed mainly at plunder and tribute, leaving most southern rulers in place as tributaries.", "Malik Kafur was a Mongol general who had gone over to the Sultan."], "statements_hi": ["1307 से 1311 के बीच दक्षिण में मलिक काफ़ूर के अभियानों का मुख्य उद्देश्य लूट और कर था, जिनमें अधिकांश दक्षिणी शासकों को करदाता बनाकर बने रहने दिया गया।", "मलिक काफ़ूर एक मंगोल सेनापति था जो सुल्तान की ओर आ गया था।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-malik-kafur' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about Sher Shah Suri:', body_hi = 'शेरशाह सूरी के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. Farid, later Sher Khan, ran his father''s jagir as a young man, checking the accounts of the village headmen and protecting the cultivators -- experience that shaped his later measures on land survey and revenue. He defeated Humayun at Chausa in 1539 and at Kannauj (Bilgram) in 1540, took the title Sher Shah and founded the Sur empire, which lasted until Humayun''s return in 1555.', explanation_hi = 'दोनों कथन सही हैं। फ़रीद, बाद में शेर ख़ान, ने युवावस्था में अपने पिता की जागीर चलाई, गाँव के मुखियाओं के हिसाब जाँचे और किसानों की रक्षा की; इसी अनुभव ने भूमि सर्वेक्षण और राजस्व पर उसके बाद के उपायों को आकार दिया। उसने 1539 में चौसा और 1540 में कन्नौज (बिलग्राम) में हुमायूँ को हराया, शेरशाह की उपाधि ली और सूर साम्राज्य की स्थापना की, जो 1555 में हुमायूँ की वापसी तक चला।', concept_group_id = 'medieval-sher-shah-origin', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["An Afghan of the Sur clan, he learnt revenue administration by managing his father''s jagir long before he became king.", "He drove Humayun out of India after defeating him at Chausa and at Kannauj."], "statements_hi": ["सूर कबीले के एक अफ़ग़ान के रूप में उसने राजा बनने से बहुत पहले अपने पिता की जागीर सँभालकर राजस्व प्रशासन सीखा।", "उसने चौसा और कन्नौज में हुमायूँ को हराकर उसे भारत से बाहर खदेड़ दिया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-sher-shah-origin' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'easy', body = 'Consider the following foreign visitors:', body_hi = 'निम्नलिखित विदेशी यात्रियों पर विचार कीजिए:', explanation = 'Three of them visited Vijayanagara. Nicolo Conti of Venice described it in about 1420; Abdur Razzaq, sent by the Timurid ruler of Herat, saw it in the 1440s and wrote of its markets and festivals; and the Portuguese Domingo Paes came in the time of Krishnadevaraya and left a detailed picture of the city. Francois Bernier was a French physician who travelled in the Mughal empire in the 1650s and 1660s, in the time of Shah Jahan and Aurangzeb.', explanation_hi = 'इनमें से तीन विजयनगर आए। वेनिस के निकोलो कोंती ने लगभग 1420 में इसका वर्णन किया; हेरात के तैमूरी शासक द्वारा भेजे गए अब्दुर रज़्ज़ाक़ ने इसे 1440 के दशक में देखा और इसके बाज़ारों तथा उत्सवों के बारे में लिखा; और पुर्तगाली डोमिंगो पेस कृष्णदेवराय के समय आए और नगर का विस्तृत चित्र छोड़ा। फ़्रांस्वा बर्नियर एक फ़्रांसीसी चिकित्सक थे जो 1650 और 1660 के दशकों में, शाहजहाँ और औरंगज़ेब के समय, मुग़ल साम्राज्य में घूमे।', concept_group_id = 'medieval-travellers-conti-razzaq-bernier', source_citation = 'NCERT Class XII, Themes in Indian History', question_data = '{"statements": ["Nicolo Conti", "Abdur Razzaq", "Domingo Paes", "Francois Bernier"], "statements_hi": ["निकोलो कोंती", "अब्दुर रज़्ज़ाक़", "डोमिंगो पेस", "फ़्रांस्वा बर्नियर"], "closing": "How many of the above visited the city of Vijayanagara?", "closing_hi": "उपर्युक्त में से कितने विजयनगर नगर आए?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-travellers-conti-razzaq-bernier' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'hard', body = 'In the eighteenth century the Peshwa at Pune became the real head of the Maratha state, while the Chhatrapati at Satara remained its formal head and great families held states of their own. Consider the following statements:', body_hi = 'अठारहवीं सदी में पुणे का पेशवा मराठा राज्य का वास्तविक प्रमुख बन गया, जबकि सतारा का छत्रपति औपचारिक प्रमुख बना रहा और बड़े परिवारों के अपने राज्य थे। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1, 2 and 3 are correct. Under the Peshwas, Maratha power spread into Malwa, Gujarat, Bundelkhand, Rajasthan, Orissa and even the Punjab, largely through the great families who collected chauth and held their own territories -- the Holkars at Indore, the Sindhias at Gwalior, the Gaekwads at Baroda and the Bhonsles at Nagpur. But their rivalries meant that, especially after Panipat (1761) and the death of the able Peshwa Madhav Rao, the British could make separate treaties with them and defeat them in turn. Statement 4 is wrong: Nagpur was the Bhonsles'' seat; the Gaekwads ruled from Baroda.', explanation_hi = 'कथन 1, 2 और 3 सही हैं। पेशवाओं के समय मराठा शक्ति मालवा, गुजरात, बुंदेलखंड, राजस्थान, उड़ीसा और पंजाब तक फैली, मुख्यतः उन बड़े परिवारों के माध्यम से जो चौथ वसूलते और अपने क्षेत्र रखते थे: इंदौर में होल्कर, ग्वालियर में सिंधिया, बड़ौदा में गायकवाड़ और नागपुर में भोंसले। पर उनकी प्रतिद्वंद्विता के कारण, विशेषकर पानीपत (1761) और योग्य पेशवा माधवराव की मृत्यु के बाद, अंग्रेज़ उनसे अलग-अलग संधियाँ कर उन्हें बारी-बारी से हरा सके। कथन 4 गलत है: नागपुर भोंसलों का केंद्र था; गायकवाड़ बड़ौदा से शासन करते थे।', concept_group_id = 'medieval-maratha-confederacy-seats', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["This loose structure helped rapid expansion, as each family pushed into new regions.", "It also weakened the Marathas against the British, who could deal with the chiefs one by one.", "The Holkars ruled from Indore and the Sindhias from Gwalior.", "The Gaekwads ruled from Nagpur."], "statements_hi": ["इस ढीली संरचना ने तेज़ विस्तार में मदद की, क्योंकि हर परिवार नए क्षेत्रों में बढ़ता गया।", "इसने अंग्रेज़ों के सामने मराठों को कमज़ोर भी किया, जो सरदारों से एक-एक कर निपट सकते थे।", "होल्कर इंदौर से और सिंधिया ग्वालियर से शासन करते थे।", "गायकवाड़ नागपुर से शासन करते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-maratha-confederacy-seats' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'hard', body = 'The Prithviraj Raso tells how four Rajput clans were born from a sacrificial fire on Mount Abu. Consider the following statements:', body_hi = 'पृथ्वीराज रासो बताता है कि चार राजपूत कुल आबू पर्वत पर एक यज्ञ की अग्नि से जन्मे। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. The four clans of the legend -- the Pratiharas, Chauhans, Paramaras and Chalukyas (Solankis) -- were among the families that rose to power from the eighth century; a purifying fire created by sages gave them a divine origin and a claim to be Kshatriyas, whatever their actual background. The Paramara king Bhoja of the eleventh century was famed as a scholar and builder. Statement 2 is wrong: the Raso, attributed to Chand Bardai, the poet of Prithviraj Chauhan, survives in versions put together much later, and its heroic legends cannot be taken as a record of origins.', explanation_hi = 'कथन 1 और 3 सही हैं। कथा के चार कुल, प्रतिहार, चौहान, परमार और चालुक्य (सोलंकी), उन परिवारों में थे जो आठवीं सदी से सत्ता में उभरे; ऋषियों द्वारा उत्पन्न शुद्धिकारी अग्नि ने उन्हें दैवी उत्पत्ति और क्षत्रिय होने का दावा दिया, उनकी वास्तविक पृष्ठभूमि चाहे जो हो। ग्यारहवीं सदी के परमार राजा भोज विद्वान और निर्माता के रूप में प्रसिद्ध थे। कथन 2 गलत है: पृथ्वीराज चौहान के कवि चंद बरदाई को श्रेय दिया जाने वाला रासो बहुत बाद में जोड़े गए रूपों में बचा है, और इसकी वीर-कथाओं को उत्पत्ति का अभिलेख नहीं माना जा सकता।', concept_group_id = 'medieval-rajput-kingdoms-agnikula-bhoja', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Historians read this Agnikula legend as a way for new ruling families to claim Kshatriya status.", "The legend is reliable contemporary evidence of the clans'' origins in the early medieval period.", "The Paramaras, one of these clans, produced Bhoja, a famous patron of learning."], "statements_hi": ["इतिहासकार इस अग्निकुल कथा को नए शासक परिवारों द्वारा क्षत्रिय दर्जे का दावा करने के एक तरीक़े के रूप में पढ़ते हैं।", "यह कथा प्रारंभिक मध्यकाल में इन कुलों की उत्पत्ति का विश्वसनीय समकालीन प्रमाण है।", "इन कुलों में से एक, परमारों, ने विद्या के प्रसिद्ध संरक्षक भोज को जन्म दिया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-rajput-kingdoms-agnikula-bhoja' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about the Varkari tradition of Maharashtra:', body_hi = 'महाराष्ट्र की वारकरी परंपरा के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct, and together they show why the tradition took such deep root. From Jnaneshwar in the thirteenth century to Tukaram in the seventeenth, the Varkari saints sang abhangas in Marathi, the language of the people. Its saints included a potter, a gardener, a tailor, a Mahar and women such as Janabai and Bahinabai, so devotion was not bounded by caste, though caste in society remained. The annual ''wari'' to Pandharpur, carrying the saints'' palanquins, still draws hundreds of thousands.', explanation_hi = 'तीनों कथन सही हैं, और मिलकर बताते हैं कि यह परंपरा इतनी गहरी क्यों जमी। तेरहवीं सदी के ज्ञानेश्वर से सत्रहवीं सदी के तुकाराम तक वारकरी संतों ने लोगों की भाषा मराठी में अभंग गाए। इसके संतों में एक कुम्हार, एक माली, एक दर्ज़ी, एक महार और जनाबाई तथा बहिणाबाई जैसी स्त्रियाँ थीं, इसलिए भक्ति जाति से बँधी नहीं थी, यद्यपि समाज में जाति बनी रही। संतों की पालकियाँ लेकर पंढरपुर की वार्षिक ''वारी'' आज भी लाखों लोगों को खींचती है।', concept_group_id = 'medieval-varkari-tradition', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Its saints composed in Marathi rather than Sanskrit, which carried devotion to ordinary people.", "It drew its saints from many castes, among them Gora the potter and Chokhamela, a Mahar.", "Its pilgrims walk each year to the temple of Vithoba at Pandharpur."], "statements_hi": ["इसके संतों ने संस्कृत के बजाय मराठी में रचना की, जिससे भक्ति आम लोगों तक पहुँची।", "इसके संत अनेक जातियों से आए, जिनमें कुम्हार गोरा और महार चोखामेला भी थे।", "इसके तीर्थयात्री हर वर्ष पंढरपुर के विठोबा मंदिर तक पैदल जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-varkari-tradition' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the early Arab and Turkish contacts with India:', body_hi = 'भारत से प्रारंभिक अरब और तुर्क संपर्कों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None is correct. Muhammad bin Qasim''s conquest of Sindh for the Umayyads in 712 went no further, as Indian powers such as the Pratiharas held the Arabs in check for centuries. Mahmud''s seventeen or so raids, between about 1000 and 1027, aimed at the treasure of temples and cities such as Mathura, Kanauj and Somnath; apart from the Punjab, which he annexed, he did not try to govern north India. Al-Biruni wrote his study of Indian society, religion and science in Arabic, around 1030, after learning Sanskrit.', explanation_hi = 'कोई भी कथन सही नहीं है। 712 में उमय्यदों के लिए मुहम्मद बिन क़ासिम की सिंध विजय आगे नहीं बढ़ी, क्योंकि प्रतिहारों जैसी भारतीय शक्तियों ने सदियों तक अरबों को रोके रखा। लगभग 1000 से 1027 के बीच महमूद के लगभग सत्रह आक्रमण मथुरा, कन्नौज और सोमनाथ जैसे मंदिरों और नगरों के ख़ज़ाने पर केंद्रित थे; पंजाब को छोड़कर, जिसे उसने मिला लिया, उसने उत्तर भारत पर शासन का प्रयास नहीं किया। अल-बिरूनी ने संस्कृत सीखकर लगभग 1030 में भारतीय समाज, धर्म और विज्ञान का अपना अध्ययन अरबी में लिखा।', concept_group_id = 'medieval-arabs-ghaznavids-albiruni', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["The Arab conquest of Sindh in 712 was followed quickly by Arab rule over much of north India.", "Mahmud of Ghazni aimed to rule the Ganga valley directly, and set up governors at Kanauj and Mathura.", "Al-Biruni, who came to India in Mahmud''s time, wrote his Kitab-ul-Hind in Persian."], "statements_hi": ["712 में सिंध की अरब विजय के बाद जल्द ही उत्तर भारत के बड़े भाग पर अरब शासन हो गया।", "महमूद ग़ज़नवी गंगा घाटी पर सीधे शासन करना चाहता था, और उसने कन्नौज तथा मथुरा में राज्यपाल नियुक्त किए।", "महमूद के समय भारत आए अल-बिरूनी ने अपनी किताब-उल-हिंद फ़ारसी में लिखी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-arabs-ghaznavids-albiruni' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Bahmani kingdom:', body_hi = 'बहमनी राज्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. Alauddin Hasan Bahman Shah founded the kingdom when the Deccan nobles rose against Delhi, and it ruled first from Gulbarga and later from Bidar. After the late fifteenth century it broke up into five sultanates, among them Bijapur, Golconda and Ahmadnagar. Statement 2 is wrong: Mahmud Gawan was a Persian, one of the ''newcomers'' (afaqis) whose rivalry with the older Deccani nobles divided the court; his execution in 1481 hastened the kingdom''s decline. He built a great madrasa at Bidar.', explanation_hi = 'कथन 1 और 3 सही हैं। जब दक्कन के सामंत दिल्ली के विरुद्ध उठे, तब अलाउद्दीन हसन बहमन शाह ने राज्य की स्थापना की, जिसने पहले गुलबर्गा और बाद में बीदर से शासन किया। पंद्रहवीं सदी के अंत के बाद यह पाँच सल्तनतों में बँट गया, जिनमें बीजापुर, गोलकुंडा और अहमदनगर थे। कथन 2 गलत है: महमूद गवाँ एक फ़ारसी था, उन ''नवागंतुकों'' (आफ़ाक़ियों) में से एक जिनकी पुराने दक्कनी सामंतों से प्रतिद्वंद्विता ने दरबार को बाँट दिया; 1481 में उसकी हत्या ने राज्य के पतन को तेज़ किया। उसने बीदर में एक बड़ा मदरसा बनवाया।', concept_group_id = 'medieval-bahmani-kingdom', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["It arose in 1347 from a revolt of nobles in the Deccan against Muhammad bin Tughlaq.", "Its great minister Mahmud Gawan was a Maratha Brahmana of the Deccan.", "Bijapur, Golconda and Ahmadnagar were among its successor states."], "statements_hi": ["यह 1347 में मुहम्मद बिन तुग़लक़ के विरुद्ध दक्कन के सामंतों के विद्रोह से उभरा।", "इसका महान मंत्री महमूद गवाँ दक्कन का एक मराठा ब्राह्मण था।", "बीजापुर, गोलकुंडा और अहमदनगर इसके उत्तराधिकारी राज्यों में थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-bahmani-kingdom' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Vaishnava bhakti in eastern India:', body_hi = 'पूर्वी भारत में वैष्णव भक्ति के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Chaitanya (1486-1533) led ecstatic kirtans through the streets of Nabadwip and later lived at Puri; singing the name of Krishna together drew people of every caste into devotion, and the Gaudiya Vaishnava tradition grew from his teaching. Statement 2 is wrong: Sankardeva''s Ekasarana (''shelter in one'') was devotion to Krishna as Vishnu, spread through village prayer halls (namghars), monasteries (satras) and plays. Statement 3 is wrong: Vallabhacharya taught Shuddhadvaita and the Pushtimarg; Dvaita was the school of Madhva.', explanation_hi = 'केवल कथन 1 सही है। चैतन्य (1486-1533) ने नवद्वीप की गलियों में भाव-विभोर कीर्तनों का नेतृत्व किया और बाद में पुरी में रहे; साथ मिलकर कृष्ण का नाम गाने ने हर जाति के लोगों को भक्ति में खींचा, और गौड़ीय वैष्णव परंपरा उनकी शिक्षा से बढ़ी। कथन 2 गलत है: शंकरदेव का एकशरण (''एक की शरण'') विष्णु रूप में कृष्ण की भक्ति थी, जो ग्राम-प्रार्थना घरों (नामघरों), मठों (सत्रों) और नाटकों से फैली। कथन 3 गलत है: वल्लभाचार्य ने शुद्धाद्वैत और पुष्टिमार्ग सिखाया; द्वैत मध्व का संप्रदाय था।', concept_group_id = 'medieval-bhakti-chaitanya-sankardeva', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Chaitanya''s congregational singing (kirtan) made devotion to Krishna a shared, public practice open to all castes.", "Sankardeva''s Ekasarana dharma in Assam centred on the worship of Shiva.", "Vallabhacharya founded the Dvaita school of Vedanta."], "statements_hi": ["चैतन्य के सामूहिक गायन (कीर्तन) ने कृष्ण-भक्ति को सभी जातियों के लिए खुला एक साझा, सार्वजनिक आचरण बना दिया।", "असम में शंकरदेव का एकशरण धर्म शिव की उपासना पर केंद्रित था।", "वल्लभाचार्य ने वेदांत के द्वैत संप्रदाय की स्थापना की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-bhakti-chaitanya-sankardeva' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the bhakti saints:', body_hi = 'भक्त संतों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct. Bhakti poetry in Tamil, Kannada, Marathi, Hindi, Bengali, Assamese and other languages was among the foundations of those literatures. The saints'' stress on personal devotion rather than ritual made room for people of every caste and for women: Ravidas was a leather-worker, Kabir a weaver, Chokhamela a Mahar. The movement began with the Alvars (devotees of Vishnu) and Nayanars (devotees of Shiva) between the sixth and ninth centuries, whose hymns are still sung in Tamil temples.', explanation_hi = 'तीनों कथन सही हैं। तमिल, कन्नड़, मराठी, हिंदी, बांग्ला, असमिया और अन्य भाषाओं की भक्ति-कविता उन साहित्यों की नींव में थी। कर्मकांड के बजाय व्यक्तिगत भक्ति पर संतों के ज़ोर ने हर जाति के लोगों और स्त्रियों के लिए जगह बनाई: रविदास चर्मकार थे, कबीर जुलाहे, चोखामेला महार। आंदोलन छठी से नौवीं सदी के बीच आलवारों (विष्णु के भक्त) और नयनारों (शिव के भक्त) से शुरू हुआ, जिनके भजन आज भी तमिल मंदिरों में गाए जाते हैं।', concept_group_id = 'medieval-bhakti-movement', source_citation = 'NCERT Class XII, Themes in Indian History', question_data = '{"statements": ["By composing in the languages of ordinary people, they helped the growth of regional literatures.", "Many of them questioned caste, and some, such as Ravidas, came from castes considered low.", "The Alvars and Nayanars of the Tamil region were among the earliest of them."], "statements_hi": ["आम लोगों की भाषाओं में रचना करके उन्होंने क्षेत्रीय साहित्य के विकास में मदद की।", "उनमें से कई ने जाति पर प्रश्न उठाए, और रविदास जैसे कुछ संत निम्न मानी जाने वाली जातियों से आए।", "तमिल क्षेत्र के आलवार और नयनार उनमें से सबसे प्रारंभिक थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-bhakti-movement' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about bhakti thinkers of the south:', body_hi = 'दक्षिण के भक्ति चिंतकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Ramanuja (eleventh-twelfth centuries), drawing on the Alvars, argued against Shankara''s view that the world and the self are illusion: if the soul is real and part of God yet distinct, then loving devotion to God becomes the path to liberation. Basavanna, a minister at the Kalachuri court in the twelfth century, founded a movement whose members wear a linga and reject caste and ritual. Statement 3 is wrong: Ramanuja worked within the Vedanta, interpreting the Upanishads and the Brahma Sutras, and never rejected the Vedas.', explanation_hi = 'कथन 1 और 2 सही हैं। आलवारों से प्रेरित रामानुज (ग्यारहवीं-बारहवीं सदी) ने शंकर के इस मत के विरुद्ध तर्क दिया कि संसार और आत्म माया हैं: यदि आत्मा सत्य है और ईश्वर का अंश होते हुए भी भिन्न है, तो ईश्वर की प्रेमपूर्ण भक्ति मोक्ष का मार्ग बनती है। बारहवीं सदी में कलचुरि दरबार के मंत्री बसवन्ना ने ऐसा आंदोलन चलाया जिसके सदस्य लिंग धारण करते हैं और जाति तथा कर्मकांड को अस्वीकार करते हैं। कथन 3 गलत है: रामानुज ने वेदांत के भीतर रहकर उपनिषदों और ब्रह्मसूत्रों की व्याख्या की, और कभी वेदों को अस्वीकार नहीं किया।', concept_group_id = 'medieval-bhakti-ramanuja-basava-jnaneshwar', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Ramanuja''s Vishishtadvaita gave a philosophical basis to devotion, holding the soul to be distinct from God yet a part of him.", "Basavanna''s Virashaiva movement rejected caste, temple worship and Brahmanical ritual.", "Ramanuja''s teaching led him to reject the authority of the Vedas."], "statements_hi": ["रामानुज के विशिष्टाद्वैत ने भक्ति को दार्शनिक आधार दिया, यह मानते हुए कि आत्मा ईश्वर से भिन्न होते हुए भी उसका अंश है।", "बसवन्ना के वीरशैव आंदोलन ने जाति, मंदिर-पूजा और ब्राह्मणवादी कर्मकांड को अस्वीकार किया।", "रामानुज की शिक्षा उन्हें वेदों के प्रामाण्य को अस्वीकार करने की ओर ले गई।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-bhakti-ramanuja-basava-jnaneshwar' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Chola kings Rajaraja I and Rajendra I:', body_hi = 'चोल राजाओं राजराज प्रथम और राजेंद्र प्रथम के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Srivijaya, on Sumatra and the Malay peninsula, controlled the straits through which ships passed to China; Rajendra I''s raid on its ports is usually explained as an effort to keep the route open for Tamil merchants, whose guilds were active across the region. Statements 2 and 3 swap father and son: Rajendra I led the march to the Ganga and built Gangaikondacholapuram to celebrate it, while his father Rajaraja I built the Brihadeshvara temple at Thanjavur, completed in about 1010.', explanation_hi = 'केवल कथन 1 सही है। सुमात्रा और मलय प्रायद्वीप पर स्थित श्रीविजय उन जलडमरूमध्यों पर नियंत्रण रखता था जिनसे जहाज़ चीन जाते थे; उसके बंदरगाहों पर राजेंद्र प्रथम के आक्रमण को प्रायः तमिल व्यापारियों के लिए मार्ग खुला रखने का प्रयास माना जाता है, जिनकी श्रेणियाँ पूरे क्षेत्र में सक्रिय थीं। कथन 2 और 3 पिता और पुत्र को आपस में बदल देते हैं: गंगा तक अभियान राजेंद्र प्रथम ने किया और उसकी याद में गंगैकोंडचोलपुरम बनाया, जबकि उनके पिता राजराज प्रथम ने तंजावुर का बृहदेश्वर मंदिर बनवाया, जो लगभग 1010 में पूरा हुआ।', concept_group_id = 'medieval-chola-rajaraja-rajendra', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Rajendra I''s naval expedition against Srivijaya, in about 1025, is linked to the protection of Chola trade with South-East Asia and China.", "Rajaraja I led the expedition to the Ganga and took the title ''Gangaikondachola''.", "The Brihadeshvara temple at Thanjavur was built by Rajendra I."], "statements_hi": ["लगभग 1025 में श्रीविजय के विरुद्ध राजेंद्र प्रथम के नौसैनिक अभियान को दक्षिण-पूर्व एशिया और चीन के साथ चोल व्यापार की रक्षा से जोड़ा जाता है।", "राजराज प्रथम ने गंगा तक अभियान का नेतृत्व किया और ''गंगैकोंडचोल'' की उपाधि ली।", "तंजावुर का बृहदेश्वर मंदिर राजेंद्र प्रथम ने बनवाया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-chola-rajaraja-rajendra' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Deccan sultanates:', body_hi = 'दक्कन सल्तनतों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Muhammad Quli Qutb Shah founded Hyderabad in 1591, and the Golconda mines produced famous diamonds, while Masulipatnam exported the painted and printed cottons of the Coromandel. Chand Bibi, a princess of the Nizam Shahi house who had been queen of Bijapur, defended Ahmadnagar against Akbar''s army in 1595-96. Statement 3 is wrong: the Gol Gumbaz, the vast domed tomb of Muhammad Adil Shah, stands at Bijapur.', explanation_hi = 'कथन 1 और 2 सही हैं। मुहम्मद क़ुली क़ुतुब शाह ने 1591 में हैदराबाद बसाया, और गोलकुंडा की खानों ने प्रसिद्ध हीरे दिए, जबकि मछलीपट्टनम से कोरोमंडल के चित्रित और छपे सूती वस्त्र निर्यात होते थे। निज़ामशाही घराने की राजकुमारी और बीजापुर की रानी रह चुकी चाँद बीबी ने 1595-96 में अकबर की सेना से अहमदनगर की रक्षा की। कथन 3 गलत है: मुहम्मद आदिल शाह का विशाल गुंबद वाला मक़बरा, गोल गुंबद, बीजापुर में है।', concept_group_id = 'medieval-deccan-sultanates', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["The Qutb Shahis of Golconda founded Hyderabad, and their kingdom grew rich on its diamond mines and the port of Masulipatnam.", "Chand Bibi defended Ahmadnagar against Akbar''s forces.", "The Gol Gumbaz stands at Golconda."], "statements_hi": ["गोलकुंडा के क़ुतुबशाहियों ने हैदराबाद बसाया, और उनका राज्य हीरे की खानों और मछलीपट्टनम बंदरगाह से समृद्ध हुआ।", "चाँद बीबी ने अकबर की सेनाओं से अहमदनगर की रक्षा की।", "गोल गुंबद गोलकुंडा में स्थित है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-deccan-sultanates' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Firuz Shah Tughlaq:', body_hi = 'फ़ीरोज़ शाह तुग़लक़ के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Firuz''s canals brought water to the dry country around Hisar, a town he founded, and parts of the western Yamuna canal were later restored by the Mughals and the British; he levied an irrigation cess on lands they watered. Statement 2 is wrong: he made the jizya a separate tax and extended it to Brahmanas, who had earlier been exempt. Statement 3 is wrong: Tughlaqabad was built by the founder of the dynasty, Ghiyasuddin Tughlaq; Firuz built Firozabad.', explanation_hi = 'केवल कथन 1 सही है। फ़ीरोज़ की नहरें उसके बसाए नगर हिसार के आसपास के सूखे इलाक़े तक पानी ले गईं, और पश्चिमी यमुना नहर के कुछ भाग बाद में मुग़लों और अंग्रेज़ों ने फिर चालू किए; उसने इनसे सींची गई भूमि पर सिंचाई कर लगाया। कथन 2 गलत है: उसने जज़िया को अलग कर बनाया और ब्राह्मणों पर भी लगाया, जो पहले मुक्त थे। कथन 3 गलत है: तुग़लक़ाबाद वंश के संस्थापक ग़यासुद्दीन तुग़लक़ ने बनवाया; फ़ीरोज़ ने फ़ीरोज़ाबाद बनवाया।', concept_group_id = 'medieval-firuz-shah-tughlaq', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["His canals from the Yamuna and the Sutlej extended cultivation in the dry tracts of Haryana.", "He abolished the jizya.", "He founded the city of Tughlaqabad."], "statements_hi": ["यमुना और सतलुज से निकाली गई उसकी नहरों ने हरियाणा के सूखे इलाकों में खेती का विस्तार किया।", "उसने जज़िया समाप्त कर दिया।", "उसने तुग़लक़ाबाद नगर की स्थापना की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-firuz-shah-tughlaq' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Ghurid conquest of north India:', body_hi = 'उत्तर भारत की ग़ोरी विजय के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None is correct. Prithviraj won at Tarain in 1191, but Ghori returned the next year with a larger army and won the second battle, which opened north India to Turkish rule; Delhi was taken soon after. The Rajput kingdoms did not combine: Jaichand of the Gahadavalas of Kanauj, Prithviraj''s rival, stood aside and was himself defeated at Chandawar in 1194. Prithviraj III belonged to the Chauhans (Chahamanas) of Ajmer and Delhi.', explanation_hi = 'कोई भी कथन सही नहीं है। पृथ्वीराज 1191 में तराइन में जीते, पर ग़ोरी अगले वर्ष बड़ी सेना के साथ लौटा और दूसरा युद्ध जीता, जिससे उत्तर भारत तुर्क शासन के लिए खुल गया; दिल्ली उसके तुरंत बाद ले ली गई। राजपूत राज्य एकजुट नहीं हुए: पृथ्वीराज के प्रतिद्वंद्वी, कन्नौज के गहड़वाल जयचंद अलग रहे और स्वयं 1194 में चंदावर में हारे। पृथ्वीराज तृतीय अजमेर और दिल्ली के चौहानों (चाहमानों) के थे।', concept_group_id = 'medieval-ghurid-conquest-tarain', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Prithviraj Chauhan''s victory over Muhammad Ghori at the first battle of Tarain secured Rajput rule in the north for half a century.", "The Gahadavalas of Kanauj joined the Chauhans to resist Ghori.", "Prithviraj III belonged to the Paramara dynasty."], "statements_hi": ["तराइन के पहले युद्ध में मुहम्मद ग़ोरी पर पृथ्वीराज चौहान की विजय ने उत्तर में आधी सदी के लिए राजपूत शासन सुरक्षित कर दिया।", "कन्नौज के गहड़वालों ने ग़ोरी का सामना करने के लिए चौहानों का साथ दिया।", "पृथ्वीराज तृतीय परमार वंश के थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-ghurid-conquest-tarain' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Humayun:', body_hi = 'हुमायूँ के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Babur had divided his lands, and Kamran, who held Kabul, Kandahar and the Punjab, gave Humayun little support, which left him facing Sher Shah with weak resources; after his defeats he wandered through Sindh and Rajasthan. Statement 2 is wrong: he took refuge with the Safavid Shah Tahmasp of Persia, whose troops helped him take Kandahar and Kabul and then return to India. Statement 3 is wrong: he died in 1556 after falling down the steps of his library in Delhi; Hemu was defeated soon after by Akbar''s forces at the second battle of Panipat.', explanation_hi = 'केवल कथन 1 सही है। बाबर ने अपने राज्य बाँट दिए थे, और काबुल, कंधार तथा पंजाब रखने वाले कामरान ने हुमायूँ का बहुत कम साथ दिया, जिससे वह कमज़ोर साधनों के साथ शेरशाह का सामना करने को रह गया; अपनी पराजयों के बाद वह सिंध और राजस्थान में भटका। कथन 2 गलत है: उसने फ़ारस के सफ़वी शाह तहमास्प के यहाँ शरण ली, जिनकी सेना ने उसे कंधार और काबुल लेने और फिर भारत लौटने में मदद दी। कथन 3 गलत है: 1556 में दिल्ली में अपने पुस्तकालय की सीढ़ियों से गिरकर उसकी मृत्यु हुई; हेमू उसके तुरंत बाद पानीपत के दूसरे युद्ध में अकबर की सेना से हारा।', concept_group_id = 'medieval-humayun-exile', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["His position was weakened by his brothers, who held Kabul, Kandahar and the Punjab and did not back him against Sher Shah.", "He regained Delhi in 1555 with the help of the Ottoman Sultan.", "He died fighting Hemu."], "statements_hi": ["उसकी स्थिति उसके भाइयों ने कमज़ोर की, जिनके पास काबुल, कंधार और पंजाब थे और जिन्होंने शेरशाह के विरुद्ध उसका साथ नहीं दिया।", "उसने 1555 में उस्मानी सुल्तान की मदद से दिल्ली फिर से जीती।", "वह हेमू से लड़ते हुए मारा गया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-humayun-exile' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Iltutmish:', body_hi = 'इल्तुतमिश के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct, and together they show how a former slave made the Sultanate a state. The Caliph''s recognition gave him a legitimacy that his rivals, also former slaves of Ghori and Aibak, lacked. His standard silver tanka and copper jital served the growing trade of the towns. And he governed through a corps of his own slave-officers, the Shamsi slaves later called the Forty, who held iqtas and commands. That same corps became so powerful that his successors, Razia among them, struggled to control it.', explanation_hi = 'तीनों कथन सही हैं, और मिलकर दिखाते हैं कि एक पूर्व दास ने सल्तनत को राज्य कैसे बनाया। ख़लीफ़ा की मान्यता ने उसे वह वैधता दी जो उसके प्रतिद्वंद्वियों, जो स्वयं ग़ोरी और ऐबक के पूर्व दास थे, के पास नहीं थी। उसका मानक चाँदी का टंका और ताँबे का जीतल नगरों के बढ़ते व्यापार के काम आया। और उसने अपने दास-अधिकारियों के दल से शासन किया, शम्सी दास जो बाद में चालीसा कहलाए, जिनके पास इक़्ता और कमान थी। यही दल इतना शक्तिशाली हो गया कि उसके उत्तराधिकारी, जिनमें रज़िया भी थी, उसे नियंत्रित करने में जूझते रहे।', concept_group_id = 'medieval-iltutmish', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["A letter of investiture he received from the Abbasid Caliph in 1229 strengthened his claim to rule.", "He standardised the coinage with the silver tanka and the copper jital.", "He relied on a corps of his own slave-officers, later known as the ''Forty''."], "statements_hi": ["1229 में अब्बासी ख़लीफ़ा से मिले मान्यता-पत्र ने उसके शासन के दावे को मज़बूत किया।", "उसने चाँदी के टंके और ताँबे के जीतल से मुद्रा को मानकीकृत किया।", "वह अपने दास-अधिकारियों के एक दल पर निर्भर था, जो बाद में ''चालीसा'' कहलाया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-iltutmish' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the reign of Jahangir:', body_hi = 'जहाँगीर के शासनकाल के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None is correct. Roe came in 1615 as ambassador of King James I of England, seeking privileges for the English East India Company, and stayed until 1619. Nur Jahan was the daughter of Mirza Ghiyas Beg, given the title I''timad-ud-Daula; Asaf Khan was her brother, and his daughter Mumtaz Mahal married the future Shah Jahan, which made the family the most powerful at court. Coins and farmans were issued in Nur Jahan''s name, a sign of her exceptional authority.', explanation_hi = 'कोई भी कथन सही नहीं है। रो 1615 में इंग्लैंड के राजा जेम्स प्रथम के राजदूत के रूप में अंग्रेज़ ईस्ट इंडिया कंपनी के लिए विशेषाधिकार माँगने आए और 1619 तक रहे। नूरजहाँ मिर्ज़ा ग़ियास बेग की पुत्री थी, जिन्हें एतमादुद्दौला की उपाधि मिली; आसफ़ ख़ान उसका भाई था, और उसकी पुत्री मुमताज़ महल का विवाह भावी शाहजहाँ से हुआ, जिससे यह परिवार दरबार में सबसे शक्तिशाली बना। नूरजहाँ के नाम पर सिक्के और फ़रमान जारी हुए, जो उसके असाधारण अधिकार का संकेत है।', concept_group_id = 'medieval-jahangir-nur-jahan-roe', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Sir Thomas Roe came to his court as the envoy of the Dutch East India Company.", "Nur Jahan was the daughter of Asaf Khan.", "No coins were ever struck in the name of a Mughal queen."], "statements_hi": ["सर टॉमस रो उसके दरबार में डच ईस्ट इंडिया कंपनी के दूत के रूप में आए।", "नूरजहाँ आसफ़ ख़ान की पुत्री थी।", "किसी मुग़ल रानी के नाम पर कभी सिक्के नहीं ढाले गए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-jahangir-nur-jahan-roe' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Vijayanagara under Krishnadevaraya:', body_hi = 'कृष्णदेवराय के समय विजयनगर के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. The Amuktamalyada tells the story of the Vaishnava saint Andal, but it also advises the king to improve harbours, welcome foreign merchants and keep the horse trade flowing -- a sign of how far Vijayanagara''s power rested on commerce. Statement 2 is wrong: his eight court poets, among them Allasani Peddana, were the Ashtadiggajas (''elephants of the eight quarters''). Statement 3 is wrong: Domingo Paes was Portuguese.', explanation_hi = 'केवल कथन 1 सही है। आमुक्तमाल्यदा वैष्णव संत आंडाल की कथा कहती है, पर यह राजा को बंदरगाह सुधारने, विदेशी व्यापारियों का स्वागत करने और घोड़ों का व्यापार चलते रखने की सलाह भी देती है, जो दिखाता है कि विजयनगर की शक्ति कितनी वाणिज्य पर टिकी थी। कथन 2 गलत है: अल्लसानि पेद्दन सहित उनके आठ दरबारी कवि अष्टदिग्गज (''आठ दिशाओं के हाथी'') कहलाते थे। कथन 3 गलत है: डोमिंगो पेस पुर्तगाली थे।', concept_group_id = 'medieval-krishnadevaraya-court', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["His Telugu work Amuktamalyada also gives advice on statecraft, such as developing ports and encouraging trade.", "The eight great poets of his court were known as the Navaratnas.", "Domingo Paes, who described his capital, was an Italian."], "statements_hi": ["उनकी तेलुगु रचना आमुक्तमाल्यदा में राजनीति पर सलाह भी है, जैसे बंदरगाहों का विकास और व्यापार को बढ़ावा।", "उनके दरबार के आठ महान कवि नवरत्न कहलाते थे।", "उनकी राजधानी का वर्णन करने वाले डोमिंगो पेस इतालवी थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-krishnadevaraya-court' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the eighteenth century:', body_hi = 'अठारहवीं सदी के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The farman let the Company trade in Bengal without customs for a small annual payment; when its servants used the privilege for their private inland trade, the Nawabs lost revenue and Indian merchants were undercut, which fed the disputes that ended at Plassey. Hyderabad, Bengal and Awadh became autonomous under governors who still acknowledged the emperor, and Nadir Shah''s sack of Delhi exposed how little force the centre had left. Statement 3 is wrong: at Panipat in 1761 the Marathas were defeated by the Afghan ruler Ahmad Shah Abdali.', explanation_hi = 'कथन 1 और 2 सही हैं। फ़रमान ने कंपनी को एक छोटे वार्षिक भुगतान पर बंगाल में बिना सीमा शुल्क व्यापार करने दिया; जब उसके कर्मचारियों ने इस विशेषाधिकार का उपयोग अपने निजी आंतरिक व्यापार के लिए किया, तो नवाबों का राजस्व घटा और भारतीय व्यापारी पिछड़े, जिससे वे विवाद बढ़े जो प्लासी पर समाप्त हुए। हैदराबाद, बंगाल और अवध ऐसे सूबेदारों के अधीन स्वायत्त हुए जो अब भी सम्राट को मानते थे, और नादिर शाह की दिल्ली लूट ने दिखा दिया कि केंद्र के पास कितनी कम शक्ति बची थी। कथन 3 गलत है: 1761 में पानीपत में मराठे अफ़ग़ान शासक अहमद शाह अब्दाली से हारे।', concept_group_id = 'medieval-later-mughals-18th-century', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Farrukhsiyar''s farman of 1717, giving the English Company duty-free trade in Bengal, later caused conflict when Company servants claimed its benefits for their own private trade.", "Nadir Shah''s invasion and the rise of autonomous regional states both reflected the weakening of the Mughal centre.", "The Third Battle of Panipat was fought between the Marathas and the Mughals."], "statements_hi": ["1717 के फ़र्रुख़सियर के फ़रमान ने अंग्रेज़ कंपनी को बंगाल में शुल्क-मुक्त व्यापार दिया, जो बाद में विवाद का कारण बना जब कंपनी के कर्मचारियों ने अपने निजी व्यापार के लिए इसके लाभ माँगे।", "नादिर शाह का आक्रमण और स्वायत्त क्षेत्रीय राज्यों का उदय, दोनों मुग़ल केंद्र के कमज़ोर होने को दर्शाते थे।", "पानीपत का तीसरा युद्ध मराठों और मुग़लों के बीच लड़ा गया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-later-mughals-18th-century' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Mewar:', body_hi = 'मेवाड़ के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Rana Kumbha (fifteenth century), a patron of music and building who also raised the fort of Kumbhalgarh, set up the Vijay Stambh to celebrate his victory over the Sultan of Malwa. Rana Sanga led a great Rajput confederacy against Babur, and its defeat broke the last attempt of the Rajputs to dominate north India; the Mughals later drew most Rajput houses into their service. Statement 3 is wrong: Alauddin Khalji took Chittor in 1303, and it fell again to Bahadur Shah of Gujarat in 1535 and to Akbar in 1568.', explanation_hi = 'कथन 1 और 2 सही हैं। संगीत और निर्माण के संरक्षक, कुंभलगढ़ का क़िला बनवाने वाले राणा कुंभा (पंद्रहवीं सदी) ने मालवा के सुल्तान पर अपनी विजय के उत्सव में विजय स्तंभ खड़ा किया। राणा सांगा ने बाबर के विरुद्ध एक बड़े राजपूत संघ का नेतृत्व किया, और उसकी हार ने उत्तर भारत पर प्रभुत्व के राजपूतों के अंतिम प्रयास को तोड़ दिया; बाद में मुग़लों ने अधिकांश राजपूत घरानों को अपनी सेवा में ले लिया। कथन 3 गलत है: अलाउद्दीन ख़लजी ने 1303 में चित्तौड़ लिया, और यह फिर 1535 में गुजरात के बहादुर शाह और 1568 में अकबर के हाथ लगा।', concept_group_id = 'medieval-mewar-kumbha-sanga', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Rana Kumbha built the Vijay Stambh at Chittor to mark a victory over the Sultan of Malwa.", "Rana Sanga''s defeat by Babur ended the hope of a Rajput revival in north India.", "Chittor was never captured by any Sultan of Delhi."], "statements_hi": ["राणा कुंभा ने मालवा के सुल्तान पर विजय की याद में चित्तौड़ में विजय स्तंभ बनवाया।", "बाबर के हाथों राणा सांगा की पराजय ने उत्तर भारत में राजपूत पुनरुत्थान की आशा समाप्त कर दी।", "चित्तौड़ को दिल्ली के किसी सुल्तान ने कभी नहीं जीता।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-mewar-kumbha-sanga' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Pala dynasty:', body_hi = 'पाल वंश के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The Khalimpur copper plate says the people made Gopala king to end matsyanyaya, ''the law of the fish'', in which the big devour the small. The Palas endowed Nalanda and founded Vikramashila and Odantapuri, and scholars from them, such as Atisha Dipankara of Vikramashila, carried Buddhism to Tibet. Statement 3 is wrong: Nalanda had flourished since Gupta times; the Palas were its later patrons.', explanation_hi = 'कथन 1 और 2 सही हैं। खालिमपुर ताम्रपत्र कहता है कि लोगों ने मत्स्यन्याय, यानी ''मछलियों का नियम'' जिसमें बड़ी मछली छोटी को निगल जाती है, समाप्त करने के लिए गोपाल को राजा बनाया। पालों ने नालंदा को दान दिए और विक्रमशिला तथा ओदंतपुरी की स्थापना की, और वहाँ के विद्वान, जैसे विक्रमशिला के अतिश दीपंकर, बौद्ध धर्म को तिब्बत ले गए। कथन 3 गलत है: नालंदा गुप्त काल से फल-फूल रहा था; पाल उसके बाद के संरक्षक थे।', concept_group_id = 'medieval-pala-dynasty', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Gopala, its founder, is said to have been chosen king to end ''matsyanyaya'', a time of anarchy.", "Their patronage of Mahayana and Vajrayana Buddhism made their kingdom a centre from which Buddhism reached Tibet.", "The Palas founded the university at Nalanda."], "statements_hi": ["कहा जाता है कि इसके संस्थापक गोपाल को ''मत्स्यन्याय'', यानी अराजकता के दौर, को समाप्त करने के लिए राजा चुना गया।", "महायान और वज्रयान बौद्ध धर्म के उनके संरक्षण ने उनके राज्य को ऐसा केंद्र बनाया जहाँ से बौद्ध धर्म तिब्बत पहुँचा।", "पालों ने नालंदा विश्वविद्यालय की स्थापना की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-pala-dynasty' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the first rulers of the Delhi Sultanate:', body_hi = 'दिल्ली सल्तनत के पहले शासकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None is correct. The label ''Slave'' or ''Mamluk'' dynasty is misleading: Aibak, Iltutmish and Balban had each once been slaves, but each founded his own line -- Iltutmish was Aibak''s slave and son-in-law, and Balban rose from among Iltutmish''s slaves. Aibak, Muhammad Ghori''s former slave and commander, only began the Qutub Minar; Iltutmish completed it. Aibak''s successor was the short-lived Aram Shah, displaced by Iltutmish in 1210; Balban came to the throne only in 1266.', explanation_hi = 'कोई भी कथन सही नहीं है। ''ग़ुलाम'' या ''मामलूक'' वंश का नाम भ्रामक है: ऐबक, इल्तुतमिश और बलबन कभी दास रहे थे, पर हर एक ने अपनी अलग वंश-परंपरा शुरू की; इल्तुतमिश ऐबक का दास और दामाद था, और बलबन इल्तुतमिश के दासों में से उठा। मुहम्मद ग़ोरी के पूर्व दास और सेनापति ऐबक ने क़ुतुब मीनार केवल शुरू की; इल्तुतमिश ने उसे पूरा किया। ऐबक का उत्तराधिकारी अल्पकालिक आरामशाह था, जिसे 1210 में इल्तुतमिश ने हटाया; बलबन 1266 में ही सिंहासन पर आया।', concept_group_id = 'medieval-qutb-ud-din-aibak-delhi-sultanate', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Aibak, Iltutmish and Balban belonged to a single family line, which is why their rule is called the ''Slave dynasty''.", "Aibak completed the Qutub Minar in his own reign.", "Aibak was succeeded directly by Balban."], "statements_hi": ["ऐबक, इल्तुतमिश और बलबन एक ही वंश-परंपरा के थे, इसीलिए उनके शासन को ''ग़ुलाम वंश'' कहा जाता है।", "ऐबक ने अपने ही शासनकाल में क़ुतुब मीनार पूरी की।", "ऐबक का सीधा उत्तराधिकारी बलबन था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-qutb-ud-din-aibak-delhi-sultanate' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following rulers:', body_hi = 'निम्नलिखित शासकों पर विचार कीजिए:', explanation = 'Four of them were Rashtrakutas. Dantidurga, a feudatory of the Badami Chalukyas, overthrew them in the mid-eighth century; his successor Krishna I had the Kailasa temple at Ellora cut from the hillside; Amoghavarsha I, who ruled from Manyakheta for over sixty years, is credited with the Kannada Kavirajamarga; and Krishna III defeated the Cholas at Takkolam in 949. Pulakeshin II was the great king of the Chalukyas of Badami, whom the Rashtrakutas later displaced.', explanation_hi = 'इनमें से चार राष्ट्रकूट थे। बादामी चालुक्यों के सामंत दंतिदुर्ग ने आठवीं सदी के मध्य में उन्हें उखाड़ा; उसके उत्तराधिकारी कृष्ण प्रथम ने एलोरा में पहाड़ी काटकर कैलास मंदिर बनवाया; मान्यखेट से साठ वर्ष से अधिक शासन करने वाले अमोघवर्ष प्रथम को कन्नड़ कविराजमार्ग का श्रेय दिया जाता है; और कृष्ण तृतीय ने 949 में तक्कोलम में चोलों को हराया। पुलकेशिन द्वितीय बादामी के चालुक्यों का महान राजा था, जिन्हें बाद में राष्ट्रकूटों ने हटाया।', concept_group_id = 'medieval-rashtrakutas', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Dantidurga", "Krishna I", "Amoghavarsha I", "Krishna III", "Pulakeshin II"], "statements_hi": ["दंतिदुर्ग", "कृष्ण प्रथम", "अमोघवर्ष प्रथम", "कृष्ण तृतीय", "पुलकेशिन द्वितीय"], "closing": "How many of the above were Rashtrakuta rulers?", "closing_hi": "उपर्युक्त में से कितने राष्ट्रकूट शासक थे?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "b", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "c", "body": "Only four", "body_hi": "केवल चार", "isCorrect": true}, {"id": "d", "body": "All five", "body_hi": "सभी पाँच", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-rashtrakutas' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about regional kingdoms:', body_hi = 'क्षेत्रीय राज्यों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Zain-ul-Abidin (1420-70) reversed the harsh policies of his predecessor, invited back Hindus who had left the valley, ended the jizya, built canals and encouraged crafts such as shawl-weaving and papier-mache, and had the Mahabharata and the Rajatarangini translated into Persian. Statement 2 is wrong: Kalhana''s Rajatarangini (twelfth century) is a history of Kashmir in Sanskrit verse. Statement 3 is wrong: Mahmud Begarha was the greatest Sultan of Gujarat, who took Champaner and Junagadh.', explanation_hi = 'केवल कथन 1 सही है। ज़ैनुल आबिदीन (1420-70) ने अपने पूर्ववर्ती की कठोर नीतियाँ पलटीं, घाटी छोड़ गए हिंदुओं को वापस बुलाया, जज़िया समाप्त किया, नहरें बनवाईं और शॉल-बुनाई तथा पेपर-माशे जैसे शिल्पों को प्रोत्साहन दिया, और महाभारत तथा राजतरंगिणी का फ़ारसी में अनुवाद करवाया। कथन 2 गलत है: कल्हण की राजतरंगिणी (बारहवीं सदी) संस्कृत पद्य में कश्मीर का इतिहास है। कथन 3 गलत है: महमूद बेगड़ा गुजरात का सबसे महान सुल्तान था, जिसने चंपानेर और जूनागढ़ लिए।', concept_group_id = 'medieval-regional-kingdoms-kashmir-gujarat', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Zain-ul-Abidin of Kashmir, who abolished the jizya and had Sanskrit works translated into Persian, is remembered as ''Budshah'', the great king.", "Kalhana''s Rajatarangini is a history of Nepal.", "Mahmud Begarha was a Sultan of Bengal."], "statements_hi": ["जज़िया समाप्त करने और संस्कृत ग्रंथों का फ़ारसी में अनुवाद करवाने वाले कश्मीर के ज़ैनुल आबिदीन को ''बडशाह'', यानी महान राजा, के रूप में याद किया जाता है।", "कल्हण की राजतरंगिणी नेपाल का इतिहास है।", "महमूद बेगड़ा बंगाल का सुल्तान था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-regional-kingdoms-kashmir-gujarat' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Sikh Gurus:', body_hi = 'सिख गुरुओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The Gurmukhi script, standardised by Guru Angad, gave the community its own written medium for the hymns later compiled in the Adi Granth. After Guru Arjan was executed on Jahangir''s orders in 1606, his son Guru Hargobind took up the two swords -- temporal (miri) and spiritual (piri) authority -- kept armed followers and built the Akal Takht facing the Harmandir. Statement 3 is wrong: Ramdaspur, later Amritsar, was founded by the fourth Guru, Guru Ram Das; Guru Gobind Singh founded the Khalsa at Anandpur in 1699.', explanation_hi = 'कथन 1 और 2 सही हैं। गुरु अंगद द्वारा मानकीकृत गुरमुखी लिपि ने समुदाय को उन भजनों के लिए अपना लिखित माध्यम दिया जो बाद में आदि ग्रंथ में संकलित हुए। 1606 में जहाँगीर के आदेश पर गुरु अर्जन की फाँसी के बाद उनके पुत्र गुरु हरगोबिंद ने दो तलवारें, यानी सांसारिक (मीरी) और आध्यात्मिक (पीरी) अधिकार, धारण कीं, सशस्त्र अनुयायी रखे और हरमंदिर के सामने अकाल तख़्त बनवाया। कथन 3 गलत है: रामदासपुर, बाद में अमृतसर, चौथे गुरु, गुरु रामदास, ने बसाया; गुरु गोबिंद सिंह ने 1699 में आनंदपुर में ख़ालसा की स्थापना की।', concept_group_id = 'medieval-sikh-gurus-angad-hargobind', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Guru Angad gave a standard form to the Gurmukhi script, in which the Gurus'' hymns were written down.", "After Guru Arjan''s execution, Guru Hargobind wore two swords, of miri and piri, and built the Akal Takht, beginning the militarisation of the community.", "Guru Gobind Singh founded the town of Ramdaspur."], "statements_hi": ["गुरु अंगद ने गुरमुखी लिपि को मानक रूप दिया, जिसमें गुरुओं के भजन लिखे गए।", "गुरु अर्जन की फाँसी के बाद गुरु हरगोबिंद ने मीरी और पीरी की दो तलवारें धारण कीं और अकाल तख़्त बनवाया, जिससे समुदाय के सैन्यीकरण की शुरुआत हुई।", "गुरु गोबिंद सिंह ने रामदासपुर नगर की स्थापना की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-sikh-gurus-angad-hargobind' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Sufi orders in India:', body_hi = 'भारत में सूफ़ी सिलसिलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. The Naqshbandis, who came to India with the Mughals, stressed the sharia and closeness to rulers in order to influence them; Sirhindi, called the ''renewer of the second millennium'', criticised Akbar''s policies and the mingling of faiths. Against Ibn Arabi''s idea that all being is one with God, which many Indian Sufis had adopted, he held that God and creation are distinct, and the unity is only in the mystic''s perception. Statement 2 is wrong: Nizamuddin Auliya was a Chishti, the disciple of Baba Farid.', explanation_hi = 'कथन 1 और 3 सही हैं। मुग़लों के साथ भारत आए नक़्शबंदी शरिया पर और शासकों को प्रभावित करने के लिए उनसे निकटता पर ज़ोर देते थे; ''दूसरी सहस्राब्दी के मुजद्दिद'' कहलाने वाले सरहिंदी ने अकबर की नीतियों और धर्मों के मेल की आलोचना की। इब्न अरबी के इस विचार के विरुद्ध, जिसे कई भारतीय सूफ़ियों ने अपनाया था, कि समस्त अस्तित्व ईश्वर से एक है, उन्होंने माना कि ईश्वर और सृष्टि भिन्न हैं, और एकता केवल रहस्यवादी की अनुभूति में है। कथन 2 गलत है: निज़ामुद्दीन औलिया चिश्ती थे, बाबा फ़रीद के शिष्य।', concept_group_id = 'medieval-sufi-orders-suhrawardi-naqshbandi', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Shaikh Ahmad Sirhindi of the Naqshbandi order opposed Akbar''s religious policies and stressed strict observance of the sharia.", "Nizamuddin Auliya belonged to the Suhrawardi order.", "Sirhindi rejected the idea of wahdat-ul-wujud (unity of being), arguing instead for wahdat-ush-shuhud (unity of appearance)."], "statements_hi": ["नक़्शबंदी सिलसिले के शेख़ अहमद सरहिंदी ने अकबर की धार्मिक नीतियों का विरोध किया और शरिया के कड़े पालन पर ज़ोर दिया।", "निज़ामुद्दीन औलिया सुहरावर्दी सिलसिले के थे।", "सरहिंदी ने वहदत-उल-वुजूद (अस्तित्व की एकता) के विचार को अस्वीकार किया और उसके स्थान पर वहदत-उश-शुहूद (प्रतीति की एकता) का तर्क दिया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-sufi-orders-suhrawardi-naqshbandi' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the ''Tripartite Struggle'' of the eighth to tenth centuries:', body_hi = 'आठवीं से दसवीं सदी के ''त्रिपक्षीय संघर्ष'' के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Kanauj, Harsha''s old capital in the heart of the fertile, trade-rich Ganga plain, carried prestige as well as wealth, so the Palas of the east, the Gurjara-Pratiharas of the west and the Rashtrakutas of the Deccan fought over it for some two centuries. None could hold it for good, and by the late tenth century all three were in decline, leaving a north India of rival regional kingdoms. Statement 3 is wrong: the Rashtrakutas were a Deccan power, ruling from Manyakheta; the Palas held Bengal.', explanation_hi = 'कथन 1 और 2 सही हैं। उपजाऊ और व्यापार-समृद्ध गंगा मैदान के हृदय में स्थित हर्ष की पुरानी राजधानी कन्नौज के साथ प्रतिष्ठा और संपत्ति दोनों जुड़ी थीं, इसलिए पूर्व के पालों, पश्चिम के गुर्जर-प्रतिहारों और दक्कन के राष्ट्रकूटों ने लगभग दो सदियों तक इसके लिए संघर्ष किया। कोई इसे स्थायी रूप से नहीं रख सका, और दसवीं सदी के अंत तक तीनों का पतन हो रहा था, जिससे उत्तर भारत प्रतिद्वंद्वी क्षेत्रीय राज्यों में बँटा रह गया। कथन 3 गलत है: राष्ट्रकूट मान्यखेट से शासन करने वाली दक्कन की शक्ति थे; बंगाल पालों के पास था।', concept_group_id = 'medieval-tripartite-struggle', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Kanauj was fought over because holding it symbolised mastery of the Ganga plain.", "The long struggle wore down all three powers, which is one reason north India was divided when the Turkish raids began.", "The Rashtrakutas, one of the three powers, were based in Bengal."], "statements_hi": ["कन्नौज के लिए इसलिए लड़ाई हुई कि उस पर अधिकार गंगा के मैदान पर प्रभुत्व का प्रतीक था।", "लंबे संघर्ष ने तीनों शक्तियों को थका दिया, जो एक कारण है कि तुर्क आक्रमणों के आरंभ के समय उत्तर भारत बँटा हुआ था।", "तीनों शक्तियों में से एक, राष्ट्रकूट, बंगाल में स्थित थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-tripartite-struggle' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Medieval', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Vijayanagara empire:', body_hi = 'विजयनगर साम्राज्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Good horses could not be bred in the south, so the rulers paid heavily for Arabian and Persian horses landed at the western ports -- one reason they cultivated the Portuguese after 1510 -- and cavalry was central to their wars. Revenue from land, temples and the trade in spices and textiles paid for it. Statement 2 is wrong: Harihara and Bukka founded the empire in 1336. Statement 3 is wrong: at Talikota (Rakshasi-Tangadi) the Vijayanagara army was defeated by an alliance of the Deccan sultanates, after which the capital was sacked.', explanation_hi = 'केवल कथन 1 सही है। दक्षिण में अच्छे घोड़े पाले नहीं जा सकते थे, इसलिए शासक पश्चिमी बंदरगाहों पर उतरने वाले अरबी और फ़ारसी घोड़ों के लिए भारी क़ीमत देते थे, यह एक कारण है कि उन्होंने 1510 के बाद पुर्तगालियों से मेल रखा, और घुड़सवार सेना उनके युद्धों का केंद्र थी। भूमि, मंदिरों और मसालों तथा वस्त्रों के व्यापार से राजस्व इसका ख़र्च उठाता था। कथन 2 गलत है: हरिहर और बुक्का ने 1336 में साम्राज्य की स्थापना की। कथन 3 गलत है: तालीकोटा (राक्षसी-तंगड़ी) में विजयनगर की सेना दक्कन सल्तनतों के गठबंधन से हारी, जिसके बाद राजधानी लूटी गई।', concept_group_id = 'medieval-vijayanagara-empire', source_citation = 'Satish Chandra, History of Medieval India (Orient BlackSwan)', question_data = '{"statements": ["Its wealth from trade let it maintain a large army, including cavalry built up with horses bought from Arab and Portuguese traders.", "The empire was founded in 1436 by Harihara and Bukka.", "At Talikota in 1565 it was defeated by the Mughal emperor Akbar."], "statements_hi": ["व्यापार से मिली संपत्ति ने उसे एक बड़ी सेना रखने दी, जिसमें अरब और पुर्तगाली व्यापारियों से ख़रीदे घोड़ों से बनी घुड़सवार सेना भी थी।", "साम्राज्य की स्थापना 1436 में हरिहर और बुक्का ने की।", "1565 में तालीकोटा में उसे मुग़ल सम्राट अकबर ने हराया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'medieval-vijayanagara-empire' returning concept_group_id;
